from abc import ABC, abstractmethod
from dirhunt.pool import Pool


class SourceInterface(ABC):
    """Abstract interface for all source providers."""

    @abstractmethod
    def add_domain(self, domain):
        """Add a domain to be scanned by this source."""
        pass

    @abstractmethod
    def callback(self, result):
        """Process a result from the source."""
        pass

    @abstractmethod
    def add_result(self, result):
        """Add a result to be processed."""
        pass

    @abstractmethod
    def add_error(self, error):
        """Add an error to be handled."""
        pass


class SessionFactoryInterface(ABC):
    """Abstract interface for session creation."""

    @abstractmethod
    def create_session(self):
        """Create and return a new session object."""
        pass


class ProcessorInterface(ABC):
    """Abstract interface for all processors."""

    @abstractmethod
    def process(self, crawler_url):
        """Process a CrawlerUrl instance."""
        pass

    @abstractmethod
    def is_applicable(self, crawler_url):
        """Check if this processor applies to the given CrawlerUrl."""
        pass


class UrlInfoInterface(ABC):
    """Abstract interface for URL info retrieval."""

    @abstractmethod
    def get_url_info(self, url):
        """Get information about a URL."""
        pass


class CrawlerInterface(ABC):
    """Abstract interface for the main crawler."""

    @abstractmethod
    def add_url(self, url):
        """Add a URL to the crawl queue."""
        pass

    @abstractmethod
    def add_domain(self, domain):
        """Add a domain to be scanned."""
        pass

    @abstractmethod
    def close(self):
        """Close the crawler and clean up resources."""
        pass


class SourcesInterface(ABC):
    """Abstract interface for the Sources container."""

    @abstractmethod
    def add_domain(self, domain):
        """Add a domain to all registered sources."""
        pass

    @abstractmethod
    def finished(self):
        """Check if all sources have finished."""
        pass
